//! Canonical registry of `<sui-*>` primitive props.
//!
//! The registry lives at `crates/sui/compiler/primitives.json` so
//! it sits next to its sibling `tokens.json`. It is regenerated by
//! `cargo run -p sui-lint --example regen_primitives` walking the
//! primitive packages and emitting the JSON shape this module loads.
//!
//! Lints `include_str!` the JSON at build time. Runtime cwd and the
//! crate-loading order do not affect what gets enforced.
//!
//! JSON shape:
//!
//! ```json
//! {
//!   "$comment": "generated — do not edit by hand. ...",
//!   "primitives": {
//!     "sui-button": {
//!       "variant": { "values": ["solid","soft","outline","ghost","default"], "default": "default" },
//!       "tone":    { "values": ["default","primary",...],                    "default": "default" }
//!     }
//!   }
//! }
//! ```
//!
//! Only enum-typed props (those with a `values` set) are validated by
//! the `sui-prop-value` rule. Bool/string/number props are still
//! recorded so future rules can validate types if we choose to.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

const PRIMITIVES_JSON: &str = include_str!("../../compiler/primitives.json");

/// One prop's registered shape.
#[derive(Debug, Clone, Deserialize)]
pub struct PropRule {
    /// Allowed string values when this prop is enum-typed.
    #[serde(default)]
    pub values: Option<Vec<String>>,
    /// Declared `type=` (bool / string / number) when given.
    #[serde(default, rename = "type")]
    pub ty: Option<String>,
    /// Declared default, when given. Used only for diagnostics today.
    #[serde(default)]
    pub default: Option<String>,
}

/// Registry: element-name (`"sui-button"`) → prop-name → rule.
pub type PrimitiveRegistry = BTreeMap<String, BTreeMap<String, PropRule>>;

#[derive(Deserialize)]
struct File {
    primitives: PrimitiveRegistry,
}

/// Load the baked-in registry. Parsed exactly once.
pub fn registry() -> &'static PrimitiveRegistry {
    static CACHE: OnceLock<PrimitiveRegistry> = OnceLock::new();
    CACHE.get_or_init(|| {
        let f: File = serde_json::from_str(PRIMITIVES_JSON)
            .expect("primitives.json must be valid JSON matching the registry shape");
        f.primitives
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_parses() {
        let r = registry();
        // The bundled registry is generated; at minimum it should
        // contain sui-button with variant + tone enums (canonical
        // primitives that the regen tool always picks up).
        let btn = r.get("sui-button").expect("sui-button missing from registry");
        let variant = btn.get("variant").expect("variant prop missing");
        assert!(variant.values.is_some(), "variant should be enum-typed");
    }
}
